<?php
require_once __DIR__.'/../config/app.php';require_once __DIR__.'/../config/koneksi.php';require_admin();$pageTitle='Data Perusahaan';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$a=$_POST['action']??'';$id=(int)($_POST['id']??0);$nama=trim($_POST['nama']??'');$alamat=trim($_POST['alamat']??'');$bidang=trim($_POST['bidang']??'');$kontak=trim($_POST['kontak']??'');
 if($a==='delete'){$pdo->prepare("DELETE FROM perusahaan WHERE id=?")->execute([$id]);flash('success','Perusahaan dihapus.');redirect('perusahaan.php');}
 if($nama==='')$errors[]='Nama perusahaan wajib diisi.';if(!$errors){if($a==='create')$q=$pdo->prepare("INSERT INTO perusahaan(nama,alamat,bidang,kontak) VALUES(?,?,?,?)");else{$q=$pdo->prepare("UPDATE perusahaan SET nama=?,alamat=?,bidang=?,kontak=? WHERE id=?");}$a==='create'?$q->execute([$nama,$alamat,$bidang,$kontak]):$q->execute([$nama,$alamat,$bidang,$kontak,$id]);flash('success','Data perusahaan disimpan.');redirect('perusahaan.php');}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM perusahaan WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$qstr=trim($_GET['q']??'');$q=$pdo->prepare("SELECT * FROM perusahaan WHERE nama LIKE ? OR bidang LIKE ? ORDER BY nama");$q->execute(["%$qstr%","%$qstr%"]);$rows=$q->fetchAll();include __DIR__.'/../partials/header.php';?>
<div class="page-head"><div><h1>Data Perusahaan</h1><div class="muted">Kelola tempat pelaksanaan PKL.</div></div></div><?php foreach($errors as $x):?><div class="alert danger"><?=e($x)?></div><?php endforeach;?>
<div class="card"><h3><?=$edit?'Edit Perusahaan':'Tambah Perusahaan'?></h3><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-grid"><?php foreach([['nama','Nama Perusahaan'],['alamat','Alamat'],['bidang','Bidang'],['kontak','Kontak/Telepon']] as $f):?><div class="field"><label><?=e($f[1])?><?= $f[0]==='nama'?' *':''?></label><input name="<?=e($f[0])?>" value="<?=e($edit[$f[0]]??'')?>" <?=$f[0]==='nama'?'required':''?>></div><?php endforeach;?></div><div class="form-actions"><button class="btn">Simpan</button><?php if($edit):?><a class="btn secondary" href="perusahaan.php">Batal</a><?php endif;?></div></form></div>
<div class="card"><form class="filters"><input name="q" value="<?=e($qstr)?>" placeholder="Cari perusahaan/bidang"><button class="btn">Cari</button></form><div class="table-wrap"><table><thead><tr><th>Nama Perusahaan</th><th>Alamat</th><th>Bidang</th><th>Kontak</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nama'])?></td><td><?=e($r['alamat'])?></td><td><?=e($r['bidang'])?></td><td><?=e($r['kontak'])?></td><td><div class="actions"><a class="btn secondary small" href="?edit=<?=$r['id']?>">Edit</a><form method="post" data-confirm="Hapus perusahaan ini?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger small">Hapus</button></form></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">Belum ada data perusahaan.</td></tr><?php endif;?></tbody></table></div></div><?php include __DIR__.'/../partials/footer.php';?>
